code.text:
variable "channel" {
  type    = string
  default = "testing"
}

source "amazon-ebs" "sandbox" {
  region        = "us-east-1"
  instance_type = "m8i.2xlarge"
  ssh_username  = "ubuntu"
  ami_name      = "rhino-ai-agent-sandbox-v1-${var.channel}-${formatdate("YYYYMMDDhhmm", timestamp())}"

  source_ami_filter {
    filters     = { name = "rhino-base-ubuntu-24-v1-release-*" }
    owners      = ["self"]
    most_recent = true
  }
}

build {
  sources = ["source.amazon-ebs.sandbox"]

  provisioner "ansible" {
    playbook_file = "./playbook.yml"
  }
}
